# Definitioin von Variablen und Zuweisung von Werten 
a = 7.123   # Der Variable a wird mit dem Wert 7.123 belegt
b = -23.457 # Der Variable b wird mit dem Wert -23.457 belegt

# Berechnungen:
x = -b/a   # Die Lösung wird als -b/a ausgerechnet und dem x zugewiesen

# Ausgabe von a und b:
print("a = ", a, ", b = ", b, sep = '')
# Ausgabe der Form der linearen Gl.:
print("Die Gleichung hat die Form: (", a, ") * x + (", b,") = 0", sep = '')
# Ausgabe der Loesung der linearen Gl.:
print("Die Lösung lautet: x = ", x, sep = '')  

print(41*'_' + "\nDas Programm ist erfolgreich beendet!")
